\begin{tabular}{lcccc}
\toprule
& \multicolumn{2}{c}{$\alpha{=}0.0$} & \multicolumn{2}{c}{$\alpha{=}1.0$} \\
\cmidrule(lr){2-3} \cmidrule(lr){4-5}
Metric & Raw $\varphi$ & Diff $\varphi$ & Raw $\varphi$ & Diff $\varphi$ \\
\midrule
